from typing import Callable

def twisted(a: int, b: int) -> int:
    if a < 0 or b < 0: raise ValueError("natural numbers required")
    if a == 0: return b
    if b == 0: return a
    return a + 2*b

def check_unit(limit: int = 20) -> bool:
    return all(twisted(0, a) == a == twisted(a, 0) for a in range(limit + 1))

if __name__ == "__main__":
    print("0 is a two-sided unit on the tested range:", check_unit())
    print("(1⋆1)⋆1 =", twisted(twisted(1, 1), 1))
    print("1⋆(1⋆1) =", twisted(1, twisted(1, 1)))

from dataclasses import dataclass
from itertools import product

@dataclass(frozen=True)
class Defect:
    triple: tuple[int, int, int]
    endpoints: tuple[int, int]

def twisted(a: int, b: int) -> int:
    return b if a == 0 else a if b == 0 else a + 2*b

def census(limit: int) -> list[Defect]:
    out: list[Defect] = []
    for a, b, c in product(range(limit + 1), repeat=3):
        left = twisted(twisted(a,b),c)
        right = twisted(a,twisted(b,c))
        if left != right: out.append(Defect((a,b,c),(left,right)))
    return out

if __name__ == "__main__":
    defects = census(8)
    print(len(defects), "defects among", 9**3, "triples")
    print(*defects[:10], sep="\n")

from typing import Callable

def twisted(a: int, b: int) -> int:
    return b if a == 0 else a if b == 0 else a + 2*b

def pentagon(a: int,b: int,c: int,d: int) -> dict[str,int]:
    o: Callable[[int,int],int] = twisted
    return {"(((ab)c)d)":o(o(o(a,b),c),d), "((a(bc))d)":o(o(a,o(b,c)),d),
            "((ab)(cd))":o(o(a,b),o(c,d)), "(a((bc)d))":o(a,o(o(b,c),d)),
            "(a(b(cd)))":o(a,o(b,o(c,d)))}

if __name__ == "__main__":
    for bracketing, value in pentagon(1,1,1,1).items():
        print(f"{bracketing:14s} -> {value}")
    print("Distinct vertices are joined by unique coherent 2-cells.")

