from itertools import product
from typing import Callable, Hashable, Sequence, TypeVar
T = TypeVar("T", bound=Hashable)

def strictness_certificate(elements: Sequence[T], op: Callable[[T,T],T]) -> tuple[bool, tuple[T,T,T,T,T] | None]:
    for a,b,c in product(elements, repeat=3):
        left, right = op(op(a,b),c), op(a,op(b,c))
        if left != right: return False, (a,b,c,left,right)
    return True, None

from itertools import product
from typing import Callable, Sequence, TypeVar
T = TypeVar("T")

def defect_table(elements: Sequence[T], op: Callable[[T,T],T]) -> list[tuple[T,T,T,T,T]]:
    result: list[tuple[T,T,T,T,T]] = []
    for a,b,c in product(elements, repeat=3):
        left, right = op(op(a,b),c), op(a,op(b,c))
        if left != right: result.append((a,b,c,left,right))
    return result

